import { DatabaseSync } from "node:sqlite";
import type { TelemetryConfig } from "./config.ts";
import {
  type Telemetry,
  type RuntimeState,
  type MetaEvent,
  createRuntimeState,
} from "./state.ts";

interface QueuedStatement {
  sql: string;
  params: readonly (string | number | null)[];
}

export function createBuffer(
  config: TelemetryConfig,
  db: DatabaseSync,
  now = () => Date.now(),
): Telemetry {
  let closed = false;
  let buffer: QueuedStatement[] = [];
  let timer: NodeJS.Timeout | null = null;
  const state = createRuntimeState();

  const schedule = () => {
    if (timer) return;
    if (config.bufferFlushMs <= 0) return;
    timer = setTimeout(() => {
      timer = null;
      flush();
    }, config.bufferFlushMs);
  };

  const cancelTimer = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  };

  const recordMeta = (
    level: "warn" | "error",
    event: MetaEvent,
    detail?: string,
  ) => {
    const sessionId = state.sessionId;
    const params: (string | number | null)[] = [
      now(),
      level,
      event,
      detail ?? null,
    ];
    if (sessionId !== undefined) {
      params.push(sessionId);
    }
    try {
      db.exec("BEGIN IMMEDIATE");
      const stmt = db.prepare(
        "INSERT INTO telemetry_meta (unix_ms, level, event, detail, session_id) VALUES (?, ?, ?, ?, ?)",
      );
      stmt.run(...params);
      db.exec("COMMIT");
    } catch (err) {
      // Best-effort failed; swallow to avoid breaking the session.
      try {
        db.exec("ROLLBACK");
      } catch {
        /* ignore */
      }
    }
  };

  const flush = () => {
    if (buffer.length === 0) return;
    const batch = buffer;
    buffer = [];
    cancelTimer();
    try {
      db.exec("BEGIN IMMEDIATE");
      for (const stmt of batch) {
        db.prepare(stmt.sql).run(...stmt.params);
      }
      db.exec("COMMIT");
    } catch (err) {
      // Restore unflushed statements for retry on next flush.
      buffer.unshift(...batch);
      const detail = err instanceof Error ? err.message : String(err);
      try {
        db.exec("ROLLBACK");
      } catch {
        /* ignore */
      }
      recordMeta("error", "write_failed", detail);
    }
  };

  const enqueue = (
    sql: string,
    params: readonly (string | number | null)[],
  ) => {
    if (closed) {
      recordMeta("warn", "buffer_drop", "enqueue after close");
      return;
    }
    buffer.push({ sql, params });
    if (config.bufferMaxRows > 0 && buffer.length >= config.bufferMaxRows) {
      flush();
    } else {
      schedule();
    }
  };

  const close = () => {
    if (closed) return;
    closed = true;
    cancelTimer();
    flush();
  };

  const meta = (
    level: "warn" | "error",
    event: MetaEvent,
    detail?: string,
  ) => {
    recordMeta(level, event, detail);
  };

  return {
    config,
    now,
    state,
    enqueue,
    meta,
    flush,
    close,
  };
}

